function renderTrackMap(track){
 const map=TRACK_MAPS[track.id];
 if(!map)return '<div class="track-map-empty">Traçado indisponível para esta pista.</div>';
 return `<svg viewBox="0 0 220 140" role="img" aria-label="Traçado de ${esc(track.name)}"><path class="track-map-base" d="${map.path}"></path><path class="track-map-outline" d="${map.path}"></path><circle class="track-map-start" cx="${map.start[0]}" cy="${map.start[1]}" r="5"></circle><text class="track-map-label" x="110" y="128" text-anchor="middle">${esc(map.label)}</text></svg>`;
}
let selectedTrackId='melbourne';
function trackInfo(){
 const track=TRACKS_2026.find(t=>t.id===selectedTrackId)||TRACKS_2026[0];
 const series=n($('trackSeries').value)||12;
  // Só a rotação vigente dos Duelos altera a ficha de pista; o mapa legado
  // TRACK_SERIES segue como referência comunitária para GPs e outras pistas.
  const duelFocus=window.GBRIntelligence?.priorityFor?.(series,track.id)||null;
  const override=duelFocus||TRACK_SERIES[series]?.[track.id];
  const driver=override?.[0]||track.driver,car=override?.[1]||track.car;
  const source=duelFocus?'rotation':track.id==='madrid'?'official':override?'community':'indicative';
 return {track,series,driver,car,source};
}
function trackWeights(car){return {
 speed:car==='speed'?65:12,
 corner:car==='corner'?65:12,
 power:car==='power'?65:12,
 qualifying:11
};}
function trackPrefsKey(){const x=trackInfo();return x.series+':'+x.track.id}
function storedTrackPrefs(){return db.trackPlans?.[trackPrefsKey()]||{}}
function readTrackPrefs(){
 const pref={laps:$('trackLaps').value?Math.floor(n($('trackLaps').value)):null,weather:$('trackWeather').value};
 for(const type of Object.keys(TRACK_TYRE)){const val=$('track'+type[0].toUpperCase()+type.slice(1)).value;pref[type]=val?Math.floor(n(val)):null}
 return pref
}
function writeTrackPrefs(){
 const p=storedTrackPrefs();$('trackLaps').value=p.laps||'';$('trackWeather').value=['dry','wet','variable'].includes(p.weather)?p.weather:'dry';
 for(const type of Object.keys(TRACK_TYRE))$('track'+type[0].toUpperCase()+type.slice(1)).value=p[type]||'';
}
function saveTrackPrefs(){
 const p=readTrackPrefs();
 if(p.laps!==null&&(p.laps<2||p.laps>100))return;
 if(Object.keys(TRACK_TYRE).some(k=>p[k]!==null&&(p[k]<1||p[k]>100)))return;
 db.trackPlans[trackPrefsKey()]=p;save();renderTrackStrategies()
}
function renderTrackDirectory(){
 const q=$('trackSearch').value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const sort=$('trackSort').value;
 const matches=TRACKS_2026.filter(t=>{
  const words=(t.name+' '+t.country).toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  return words.includes(q)&&(sort==='all'||(window.GBRIntelligence?.priorityFor?.(n($('trackSeries').value),t.id)?.[1]||TRACK_SERIES[n($('trackSeries').value)]?.[t.id]?.[1]||t.car)===sort);
 });
 $('trackDirectory').innerHTML=matches.map(t=>{
 const chosen=t.id===selectedTrackId;
 return `<button type="button" class="track-tile ${chosen?'selected':''}" data-track-id="${esc(t.id)}" aria-pressed="${chosen}"><span class="track-tile-icon">◈</span><span class="track-tile-body"><b>${esc(t.name)}</b><small>${esc(t.country)}</small></span><span class="track-tile-arrow">↗</span></button>`;
 }).join('');
 $('trackDirectoryEmpty').classList.toggle('hide',matches.length>0);
 document.querySelectorAll('[data-track-id]').forEach(button=>button.onclick=()=>{
  selectedTrackId=button.dataset.trackId;renderTrackDirectory();renderRaces();
  if(window.innerWidth<821)$('trackAnalysis').scrollIntoView({behavior:'smooth',block:'start'});
 });
}
function trackDriverPair(driver,series){
 return db.drivers.filter(d=>d.owned&&n(d.series)<=series&&n(d.level)>0).map(d=>({data:d,points:n(d[driver])*0.65+n(d.overtaking)*0.07+n(d.defending)*0.07+n(d.raceStart)*0.07+n(d.tyreUse)*0.07+n(d.qualifying)*0.07})).sort((a,b)=>b.points-a.points).slice(0,2);
}
function trackCarScore(set,w){if(set.chosen.length!==set.required.length)return null;
 const total=Object.entries(w).reduce((sum,[key,v])=>sum+n(set.totals[key])*v,0)/100;
 return total;
}
function trackCompareVariants(car,series){
 const learning=window.GBRRecommendations?.evidence?.(db,{series,trackId:selectedTrackId,baseWeights:trackWeights(car)});
 const variants=[
 {id:'circuit',name:'Foco na pista',description:'Enfatiza o atributo prioritário do circuito.',w:trackWeights(car),pit:'none'},
 {id:'balanced',name:'Equilibrado',description:'Distribui importância por todos os atributos.',w:profiles.balanced,pit:'none'},
 {id:'qualifying',name:'Classificação',description:'Dá mais peso à posição de largada.',w:profiles.qualifying,pit:'none'},
 {id:'pit',name:'Box mais rápido',description:'Sacrifica parte do desempenho para reduzir tempo-base de parada.',w:trackWeights(car),pit:'strong'}
 ];
 if(learning?.hasExperiment)variants.push({id:'gbr',name:'Inteligência GBR · teste',description:'Hipótese baseada em corridas revisadas. Não garante vitória.',w:learning.weights,pit:'none',learning});
 // Comparação sob a mesma escala da pista; o modo pit tem trade-off próprio.
 return variants.map(v=>{
  const build=optimize(v.w,series,v.pit);
  const trackScore=trackCarScore(build,trackWeights(car));
  return {...v,build,trackScore};
 });
}
function renderTrackSetup(){
 const {track,series,driver,car}=trackInfo();
 const variants=trackCompareVariants(car,series),primary=variants[0],pilots=trackDriverPair(driver,series);
 const valid=primary.trackScore!==null;
 const learned=window.GBRRecommendations?.evidence?.(db,{series,trackId:track.id,baseWeights:trackWeights(car)});
 const alternatives=window.GBRRecommendations?.candidates?.(db,{series,trackId:track.id,baseWeights:trackWeights(car)})||[];
 $('trackUseSetup').disabled=!valid;
 $('trackBestSetup').innerHTML=valid?`<div class="track-setup-metrics">${Object.entries(TRACK_CAR).map(([k,label])=>`<div class="track-metric"><small>${esc(label)}</small><strong>${n(primary.build.totals[k]).toFixed(0)}</strong></div>`).join('')}</div><div class="track-setup-parts">${primary.build.chosen.map(p=>`<div class="track-part"><small>${esc(p.category)}</small><span class="gbr-inline-art">${window.GBRCardArt?.thumb?.(p,'parts')||''}<b>${esc(p.name)}</b></span><span>Nv. ${n(p.level)} · ${esc(p.rarity)} · Série ${n(p.series)}</span></div>`).join('')}</div><p class="muted mini">Pit stop — soma do indicador das peças: <strong>${n(primary.build.totals.pit).toFixed(2)} s</strong> (comparação; não representa tempo total de box).</p>`:'<div class="warn">Não há peças cadastradas em todas as posições elegíveis. Em <b>Minha garagem</b>, marque as peças que possui e informe os níveis para desbloquear o cálculo.</div>';
 $('trackBestDrivers').innerHTML=`<h3>Dupla de pilotos • foco em ${esc(TRACK_DRIVER[driver])}</h3>${pilots.length===2?`<div class="track-driver-grid">${pilots.map((d,i)=>`<div class="track-driver-card"><span class="kicker">PILOTO ${i+1}</span><span class="gbr-inline-art">${window.GBRCardArt?.thumb?.(d.data,'drivers')||''}<b>${esc(d.data.name)}</b></span><small>${esc(d.data.rarity)} · nível ${n(d.data.level)} · ${esc(TRACK_DRIVER[driver])}: ${n(d.data[driver])}</small></div>`).join('')}</div>`:'<div class="warn">Cadastre pelo menos dois pilotos elegíveis na garagem. A recomendação só usa pilotos que você possui.</div>'}`;
 $('trackComparison').innerHTML=variants.map(v=>{
  const valid=v.trackScore!==null;
  const score=valid?v.trackScore.toFixed(1):'—';
  const baseline=primary.trackScore;
  const delta=valid&&baseline!==null?v.trackScore-baseline:null;
  const percent=valid&&baseline!==null&&baseline!==0?Math.max(6,Math.min(100,100*v.trackScore/baseline)):0;
  return `<div class="track-compare-row"><div class="track-compare-main"><b>${esc(v.name)} ${v.id==='circuit'?'<span class="track-recommend-tag">PISTA</span>':''}</b><small>${esc(v.description)}</small><div class="track-progress"><i style="width:${Number.isFinite(percent)?percent:0}%"></i></div></div><div class="track-compare-score"><strong>${score}</strong><small>${delta===null?'Sem dados':delta===0?'Referência':(delta>0?'+':'')+delta.toFixed(1)+' vs. foco'}</small></div></div>`
 }).join('')+`<p class="muted mini">Score comparável somente dentro desta pista, ponderado pelos atributos relevantes. Para entender o benefício do box, compare também as somas de pit stop: ${variants.map(v=>`${esc(v.name)} ${n(v.build.totals.pit).toFixed(2)}s`).join(' • ')}. Os níveis de bateria são preservados, mas seus atributos específicos de overtake não constam desta base.</p>`;
 const experiment=variants.find(v=>v.id==='gbr');
 const favorite=alternatives.find(f=>f.validated)||alternatives[0];
 const learnedText=learned?.message||'Sem histórico confiável nesta pista/série.';
 const favText=favorite?`${esc(favorite.name)} · ${favorite.sample} corrida(s) confirmada(s)${favorite.validated?` · ${favorite.wins} vitória(s)`:' · dados insuficientes para taxa confiável'}`:'Nenhum favorito elegível vinculado a esta pista.';
 $('trackComparison').insertAdjacentHTML('beforeend',`<div class="gbr-reco-inline"><div><b>Inteligência GBR</b><p>${esc(learnedText)}</p><small>${favText}</small></div>${experiment?'<button type="button" class="btn outline" id="trackTryGBR">TESTAR NO MONTADOR →</button>':''}</div>`);
 if(experiment)$('trackTryGBR').onclick=()=>openBuilderFromTrack(series,track.id,experiment.w,true);
}
function tyrePlans(laps,limits,maxStints){
 const options=Object.entries(limits).filter(([k,v])=>v&&v>0&&k!=='wet');
 if(!options.length||!laps)return [];
 const sequences=[];
 function visit(start,chosen,count){
  if(chosen.length===count){
   const capacity=chosen.reduce((a,k)=>a+limits[k],0);
   if(capacity<laps)return;
   // Aloca no mínimo uma volta por stint, sem ultrapassar a duração indicada pelo jogador.
   let remaining=laps;const stints=[];
   for(let i=0;i<chosen.length;i++){
    const laterMax=chosen.slice(i+1).reduce((a,k)=>a+limits[k],0);
    const take=Math.min(limits[chosen[i]],remaining-(chosen.length-i-1));
    if(take<1)return;
    const adjusted=Math.max(1,remaining-laterMax);
    const nLaps=Math.max(take<adjusted?adjusted:take,1);
    stints.push({type:chosen[i],laps:nLaps});remaining-=nLaps;
   }
   if(remaining!==0)return;
   const kinds=new Set(chosen);
   sequences.push({stints,stops:count-1,diversity:kinds.size,softCount:chosen.filter(k=>k==='soft').length});return;
  }
  for(let i=start;i<options.length;i++)visit(i,[...chosen,options[i][0]],count);
 }
 for(let count=1;count<=maxStints;count++)visit(0,[],count);
 sequences.sort((a,b)=>a.stops-b.stops||b.diversity-a.diversity||b.softCount-a.softCount);
 // Três opções diferentes priorizando número de paradas e compostos.
 const result=[],ids=new Set();
 for(const plan of sequences){const id=plan.stints.map(s=>s.type).join('+');if(ids.has(id))continue;result.push(plan);ids.add(id);if(result.length>=3)break}
 return result;
}
function renderTrackStrategies(){
 const {track}=trackInfo(),p=readTrackPrefs();
 const laps=p.laps,tyres=Object.entries(TRACK_TYRE).filter(([key])=>p[key]&&p[key]>=1);
 let text='';
 if(!laps||laps<2||laps>100){text=`<div class="track-empty-strategy"><b>Informe as voltas da corrida</b><p>Assim que você indicar a duração real da corrida e os stints possíveis dos pneus, o laboratório irá montar alternativas de 0, 1 ou 2 paradas.</p></div>`;}
 else if(p.weather==='variable'){text=`<div class="track-empty-strategy"><b>${laps} voltas · Clima variável</b><p>Prepare os dois compostos seco e chuva. A estratégia depende de quando começa a chover; não é seguro calcular a volta de troca sem a previsão exibida no jogo.</p></div>`;}
 else if(p.weather==='wet'){
 const w=p.wet;
 if(!w){text=`<div class="track-empty-strategy"><b>${laps} voltas · Pista molhada</b><p>Informe o número conservador de voltas que um pneu de chuva aguenta antes de perder desempenho.</p></div>`;}
 else {const stops=Math.max(0,Math.ceil(laps/w)-1);let remain=laps,stints=[];while(remain>0){const v=Math.min(remain,w);stints.push(v);remain-=v}
 text=`<div class="track-strategy-card"><div><b>Chuva · ${laps} voltas</b><span class="pill">${stops} parada(s)</span></div><div class="track-stint-flow">${stints.map((val,i)=>`<span class="track-stint wet">Chuva ${val}v</span>${i<stints.length-1?'<span class="track-flow-arrow">→</span>':''}`).join('')}</div><p class="muted mini">Plano condicional: só vale se a pista permanecer molhada durante toda a corrida e a duração informada se confirmar.</p></div>`;}
 }
 else {
  const limits={soft:p.soft,medium:p.medium,hard:p.hard};
  if(!tyres.some(([key])=>key!=='wet')){text=`<div class="track-empty-strategy"><b>${laps} voltas · Pista seca</b><p>Informe a vida útil em voltas de pelo menos um pneu seco (Macio, Médio ou Duro). A partir daí serão mostrados stints e paradas calculados.</p></div>`;}
  else {const plans=tyrePlans(laps,limits,3);text=plans.length?plans.map((plan,i)=>`<div class="track-strategy-card"><div><b>${i===0?'Menos paradas':'Alternativa '+(i+1)}</b><span class="pill">${plan.stops} parada(s)</span></div><div class="track-stint-flow">${plan.stints.map((s,j)=>`<span class="track-stint ${s.type}">${TRACK_TYRE[s.type]} ${s.laps}v</span>${j<plan.stints.length-1?'<span class="track-flow-arrow">→</span>':''}`).join('')}</div></div>`).join(''):`<div class="warn">A durabilidade informada não cobre ${laps} voltas com até 2 paradas. Verifique os valores ou considere mais paradas.</div>`}
 }
 $('trackStrategies').innerHTML=text+`<p class="muted mini" style="margin-top:12px">São combinações viáveis com as durações informadas, não uma previsão oficial de vitória. Confira pneus, tráfego, boost, pit stop, chuva e gestão dos pilotos durante a corrida.</p>`;
 $('trackWearInfo').textContent=track.nature==='tecnica'?'Pista técnica: curvas repetidas exigem observar de perto o desgaste real de cada composto.':track.nature==='rapida'?'Pista rápida: avalie estabilidade nos setores velozes e o desgaste no ritmo de ataque.':'Pista mista: compare desgaste em retomadas de velocidade e em trechos de curvas; confirme no jogo.';
}
function renderRaces(){
 const {track,series,driver,car,source}=trackInfo();
 $('trackTitle').textContent=track.name;$('trackSubtitle').textContent=track.description;
 $('trackCountry').textContent=track.country;
 $('trackMapVisual').innerHTML=renderTrackMap(track);
 $('trackPriorities').innerHTML=`<div class="track-priority"><small>ATRIBUTO PRIORITÁRIO DO CARRO</small><strong>${esc(TRACK_CAR[car])}</strong><span>${source==='official'?'Confirmado pela equipe F1 Clash':source==='rotation'?'Rotação 21/10–03/11 fornecida pelo responsável':'Baseado na referência de pista/série'}</span></div><div class="track-priority"><small>ATRIBUTO PRIORITÁRIO DO PILOTO</small><strong>${esc(TRACK_DRIVER[driver])}</strong><span>Valorizado na seleção da sua dupla de pilotos</span></div>`;
 $('trackPrioritySource').textContent=source==='indicative'?'Perfil indicativo: confirme no jogo.':source==='rotation'?'Prioridades da rotação informada para a série; confirme no jogo.':'Prioridades orientativas para esta pista e série; confirme no jogo.';
 writeTrackPrefs();renderTrackStrategies();renderTrackSetup();
}
